css:
:root{
  /* === Brand palette (tune these to match the proposal) === */
  --brand-bg: #0F172A;       /* deep navy */
  --brand-accent: #38BDF8;   /* soft cyan accent */
  --brand-accent-2: #22D3EE; /* secondary accent */
  --ink-900: #0B1220;
  --ink-700: #334155;
  --ink-600: #475569;
  --ink-500: #64748B;
  --ink-300: #CBD5E1;
  --ink-200: #E2E8F0;
  --ink-100: #F1F5F9;
  --card-bg: #FFFFFF;

  --radius: 16px;
  --shadow: 0 8px 24px rgba(2,6,23,.08);
}

*{ box-sizing:border-box; }
body{
  margin:0;
  font: 14px/1.55 system-ui, -apple-system, Segoe UI, Roboto, "Helvetica Neue", Arial, "Noto Sans", "Liberation Sans", sans-serif;
  color: var(--ink-900);
  background: linear-gradient(180deg, #0f172a 0%, #0b1220 12rem, #f8fafc 12rem, #f8fafc 100%);
  -webkit-print-color-adjust: exact !important;
  print-color-adjust: exact !important;
}

.page{
  max-width: 920px;
  margin: 48px auto;
  padding: 0 24px 48px;
}

/* Header */
.hero{
  background: linear-gradient(120deg, var(--brand-bg), #111827 60%);
  color: #E5F6FF;
  border-radius: var(--radius);
  padding: 28px;
  box-shadow: var(--shadow);
  display: grid;
  grid-template-columns: 120px 1fr auto;
  gap: 20px;
  align-items: center;
}
.logo{
  width: 100%;
  height: 100px;
  border-radius: 12px;
  background: linear-gradient(135deg, rgba(56,189,248,.12), rgba(34,211,238,.06));
  display:flex;align-items:center;justify-content:center;
  color:#8BE9FF;
  font-weight: 600;
  text-align:center;
  padding: 8px;
}
.logo img{ max-width:100%; max-height:100%; object-fit:contain; }

.title h1{
  margin: 0 0 6px;
  font-size: 26px;
  letter-spacing: .3px;
}
.title .subtitle{
  margin: 0;
  color: #BFEFFF;
  font-weight: 500;
}
.ref{
  text-align:right;
  color:#D7F7FF;
}
.ref small{ opacity:.8; }

/* Meta cards */
.grid{
  display:grid;
  grid-template-columns: 1.1fr .9fr;
  gap: 18px;
  margin-top: 18px;
}
.card{
  background: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 16px 18px;
  border: 1px solid var(--ink-200);
}
.kv{
  display:grid;
  grid-template-columns: 160px 1fr;
  gap: 8px 14px;
  align-items:center;
}
.muted{ color: var(--ink-600); }
.pill{
  background: linear-gradient(135deg, rgba(56,189,248,.15), rgba(34,211,238,.12));
  color: #0EA5E9;
  border: 1px solid rgba(56,189,248,.35);
  display:inline-block;
  padding: 4px 8px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 12px;
}

/* Table */
table{
  width: 100%;
  border-collapse:separate;
  border-spacing:0;
  overflow:hidden;
  border-radius: calc(var(--radius) - 4px);
  box-shadow: var(--shadow);
  border: 1px solid var(--ink-200);
  background: var(--card-bg);
}
thead th{
  text-align:left;
  font-size:12px;
  color:#0EA5E9;
  background: linear-gradient(180deg, rgba(56,189,248,.16), rgba(56,189,248,.06));
  padding: 10px 12px;
  border-bottom: 1px solid rgba(56,189,248,.35);
}
tbody td{
  padding: 10px 12px;
  border-bottom: 1px solid var(--ink-100);
}
tbody tr:last-child td{ border-bottom: none; }
tbody tr:nth-child(odd) td{ background: #FCFDFF; }
.num{ text-align:right; white-space:nowrap; }
.small{ color: var(--ink-600); font-size: 12px; }

/* Two-column body */
.content{
  display:grid;
  grid-template-columns: 1.75fr 1fr;
  gap: 18px;
  margin-top: 18px;
}

/* Totals */
.totals{
  display:grid; gap:10px;
}
.totals .row{
  display:flex; justify-content:space-between; align-items:center;
  padding: 10px 12px;
  background: var(--card-bg);
  border: 1px solid var(--ink-200);
  border-radius: 12px;
}
.totals .row.emph{
  background: linear-gradient(135deg, rgba(34,211,238,.12), rgba(56,189,248,.08));
  border-color: rgba(56,189,248,.45);
  font-weight:700;
}
.totals .label{ color: var(--ink-700); }
.totals .value{ font-feature-settings:"tnum"; font-variant-numeric: tabular-nums; }

/* Tags list */
.taglist{
  display:flex; flex-wrap:wrap; gap:8px;
}
.tag{
  padding:6px 10px; border-radius:999px; font-size:12px; font-weight:600;
  color:#0F172A; background:#E6F9FF; border:1px solid rgba(56,189,248,.35);
}

/* Footer note */
.note{
  margin-top: 22px;
  color: var(--ink-600);
  font-size: 12px;
}

/* Print */
@page{ size: A4; margin: 18mm; }
@media print{
  body{ background:#fff; }
  .page{ margin:0; padding:0; }
  .hero{ -webkit-print-color-adjust: exact; print-color-adjust: exact; }
}
